import React from "react";
import {
  FaLinkedin,
  FaMapMarkerAlt,
  FaEnvelope,
  FaGithub,
  FaPaperPlane
} from "react-icons/fa";

const Contact = () => {
  return (
    <>
      <style>{`

        *{ box-sizing:border-box; }
        body{ overflow-x:hidden; }

        .contact-container {
          min-height: 100vh;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          padding: 60px 8vw;
          text-align: center;
          position: relative;
        }

        /* 🔵 Glow background (match Skills page) */
        .glow {
          position: absolute;
          width: 400px;
          height: 400px;
          background: radial-gradient(circle, #38BDF8, transparent);
          top: -120px;
          right: -80px;
          filter: blur(100px);
          opacity: 0.2;
          pointer-events: none;
        }

        .contact-title {
          font-size: 44px;
          color: #38BDF8;
          margin-bottom: 10px;
        }

        .contact-desc {
          color: #94a3b8;
          font-size: 15px;
          max-width: 520px;
          margin: 0 auto 50px;
          line-height: 1.6;
        }

        /* 🔥 GRID */
        .contact-info {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
          gap: 25px;
        }

        /* 💎 CARD */
        .info-card {
          background: rgba(255, 255, 255, 0.04);
          border: 1px solid rgba(56,189,248,0.2);
          backdrop-filter: blur(12px);
          padding: 28px;
          border-radius: 16px;
          transition: all 0.3s ease;
          position: relative;
          overflow: hidden;
        }

        /* subtle glow hover */
        .info-card::before{
          content:"";
          position:absolute;
          inset:0;
          background: radial-gradient(circle at top, rgba(56,189,248,0.15), transparent 70%);
          opacity:0;
          transition:0.3s;
        }

        .info-card:hover::before{
          opacity:1;
        }

        .info-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 30px rgba(56,189,248,0.25);
        }

        .icon {
          font-size: 26px;
          margin-bottom: 14px;
          color: #38BDF8;
        }

        h3 {
          margin-bottom: 8px;
          font-size: 18px;
        }

        p {
          color: #cbd5e1;
          font-size: 14px;
          word-break: break-all;
        }

        a {
          text-decoration: none;
          color: inherit;
        }

        a:hover {
          color: #38BDF8;
        }

        /* 🚀 CTA SECTION */
        .cta {
          margin-top: 70px;
          padding: 30px;
          border-radius: 18px;
          background: linear-gradient(
            135deg,
            rgba(56,189,248,0.15),
            rgba(56,189,248,0.05)
          );
          border: 1px solid rgba(56,189,248,0.25);
        }

        .cta h2 {
          font-size: 22px;
          margin-bottom: 10px;
        }

        .cta p {
          color: #94a3b8;
          margin-bottom: 20px;
        }

        .cta a {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          padding: 10px 18px;
          border-radius: 25px;
          background: #38BDF8;
          color: #020617;
          font-weight: 500;
          transition: 0.3s;
        }

        .cta a:hover {
          transform: translateY(-2px);
          box-shadow: 0 0 15px #38BDF8;
        }

      `}</style>

      <div className="contact-container">

        <div className="glow"></div>

        <h1 className="contact-title">Connect With Me</h1>

        <p className="contact-desc">
          Open to internships, collaborations, and exciting tech opportunities. 
          Let’s build something impactful together.
        </p>

        <div className="contact-info">

          {/* EMAIL */}
          <div className="info-card">
            <FaEnvelope className="icon" />
            <h3>Email</h3>
            <a
              href="https://mail.google.com/mail/?view=cm&fs=1&to=swethaa1805@email.com"
              target="_blank"
              rel="noopener noreferrer"
            >
              <p>swethaa1805@email.com</p>
            </a>
          </div>

          {/* LINKEDIN */}
          <div className="info-card">
            <FaLinkedin className="icon" />
            <h3>LinkedIn</h3>
            <a
              href="https://www.linkedin.com/in/swetha-a-0b1712382/"
              target="_blank"
              rel="noopener noreferrer"
            >
              <p>linkedin.com/in/swetha-a</p>
            </a>
          </div>

          {/* GITHUB */}
          <div className="info-card">
            <FaGithub className="icon" />
            <h3>GitHub</h3>
            <a
              href="https://github.com/Swethaa1805"
              target="_blank"
              rel="noopener noreferrer"
            >
              <p>github.com/Swethaa1805</p>
            </a>
          </div>

          {/* LOCATION */}
          <div className="info-card">
            <FaMapMarkerAlt className="icon" />
            <h3>Location</h3>
            <p>Chennai, India</p>
          </div>

        </div>

        {/* 🚀 FINAL CTA */}
        <div className="cta">
          <h2>Let’s Work Together</h2>
          <p>
            Interested in collaborating or have an opportunity? Feel free to reach out.
          </p>

          <a
            href="https://mail.google.com/mail/?view=cm&fs=1&to=swethaa1805@email.com"
            target="_blank"
            rel="noopener noreferrer"
          >
            <FaPaperPlane /> Send Message
          </a>
        </div>

      </div>
    </>
  );
};

export default Contact;
